        //String Message_Title = "Error Alert";
        public Items()
        {
            InitializeComponent();
            gridView1.OptionsFind.FindFilterColumns = "Name";
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();


        }

        private void search_inp_EditValueChanged(object sender, EventArgs e)
        {
            if (gridView1.OptionsFind.ToString() != "")
            {
                //XtraMessageBox.Show("Testing");
                if (search_filter_cmb.SelectedIndex == 0)
                {
                    gridView1.OptionsFind.FindFilterColumns = "*";
                }
                else if (search_filter_cmb.SelectedIndex == 1)
                {
                    gridView1.OptionsFind.FindFilterColumns = "Name";
                }
                else if (search_filter_cmb.SelectedIndex == 2)
                {
                    gridView1.OptionsFind.FindFilterColumns = "Group";

                }
                else if (search_filter_cmb.SelectedIndex == 3)
                {
                    gridView1.OptionsFind.FindFilterColumns = "Category";

                }
                else if (search_filter_cmb.SelectedIndex == 4)
                {
                    gridView1.OptionsFind.FindFilterColumns = "Manufacturer";

                }
            }
            gridView1.ApplyFindFilter(search_inp.Text);
        }

        private void list_MouseDoubleClick(object sender, MouseEventArgs e)
        {
            
        }

        private void search_filter_cmb_SelectedIndexChanged(object sender, EventArgs e)
        {
            search_inp.Text = "";
        }

        public void Refresh_Grid_Data()
        {
            search_inp.Text = null;
            search_filter_cmb.SelectedIndex = 0;
            is_active_item_chkbx.CheckState = CheckState.Checked;
            this.Enabled = false;
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
            items_list.Update();
            this.Enabled = true;
            search_inp.Focus();
        }

        private void refresh_btn_Click(object sender, EventArgs e)
        {
            Refresh_Grid_Data();
        }

        private void create_new_btn_Click(object sender, EventArgs e)
        {
            search_inp.Focus();
            UC_Opener_Form form = new UC_Opener_Form("New Item",new New_Item());
            form.Show(this);
        }

        private void Items_List_Load(object sender, EventArgs e)
        {
            search_inp.Focus();
        }

        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                Item item = new Item();
                Items_Controller items_controller = new Items_Controller();
                Item source_item = items_controller.Get_Item(Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns[0])));
                item.Id = source_item.Id;
                item.Name = source_item.Name;
                item.Unicode = source_item.Unicode;
                item.Unit_Id = source_item.Unit_Id;
                item.Packing = source_item.Packing;
                item.Cash_Rate = source_item.Cash_Rate;
                item.Advance_Price = source_item.Advance_Price;
                item.No_Of_Installments = source_item.No_Of_Installments;
                item.Monthly_EMI_Price = source_item.Monthly_EMI_Price;
                item.Model_Id = source_item.Model_Id;
                item.Purchase_Rate = source_item.Purchase_Rate;
                item.Sale_Rate = source_item.Sale_Rate;
                item.Unit_Cost = source_item.Unit_Cost;
                item.Sale_Discount = source_item.Sale_Discount;
                item.Is_Active = source_item.Is_Active;
                item.Reorder_Level = source_item.Reorder_Level;
                item.Manufacturer_Id = source_item.Manufacturer_Id;
                item.Group_id = source_item.Group_id;
                item.Category_Id = source_item.Category_Id;
                Edit_Item edit_item = new Edit_Item(item);
                edit_item.items = this;
                edit_item.Show(this);
            }
        }

        private void items_list_Click(object sender, EventArgs e)
        {

        }

        public void Controls_List(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.F1 || (e.KeyCode == Keys.Down && search_inp.ContainsFocus))
            {
                gridView1.Focus();
            }
            if ((e.KeyCode == Keys.F2 || e.KeyCode == Keys.Enter) && items_list.ContainsFocus == true)
            {
                if (gridView1.DataRowCount > 0)
                {
                    Item item = new Item();
                    Items_Controller items_controller = new Items_Controller();
                    Item source_item = items_controller.Get_Item(Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns[0])));
                    item.Id = source_item.Id;
                    item.Name = source_item.Name;
                    item.Unit_Id = source_item.Unit_Id;
                    item.Packing = source_item.Packing;
                    item.Purchase_Rate = Convert.ToDouble(gridView1.GetFocusedRowCellValue(gridView1.Columns[4]));
                    item.Sale_Rate = Convert.ToDouble(gridView1.GetFocusedRowCellValue(gridView1.Columns[5]));
                    item.Unit_Cost = Convert.ToDouble(gridView1.GetFocusedRowCellValue(gridView1.Columns[6]));
                    item.Sale_Discount = Convert.ToDouble(gridView1.GetFocusedRowCellValue(gridView1.Columns[7]));
                    item.Is_Active = Convert.ToBoolean(gridView1.GetFocusedRowCellValue(gridView1.Columns[8]));
                    item.Reorder_Level = Convert.ToDouble(gridView1.GetFocusedRowCellValue(gridView1.Columns[9]));
                    item.Manufacturer_Id = source_item.Manufacturer_Id;
                    item.Group_id = source_item.Group_id;
                    item.Category_Id = source_item.Category_Id;
                    Edit_Item edit_item = new Edit_Item(item);
                    edit_item.items = this;
                    edit_item.Show(this);
                }
            }
            if (e.KeyCode == Keys.F3 || (e.Control && e.KeyCode == Keys.F))
            {
                search_inp.Focus();
            }
            if (e.KeyCode == Keys.F6 || (e.Control && e.KeyCode == Keys.N))
            {
                search_inp.Focus();
                UC_Opener_Form form = new UC_Opener_Form("New Item", new New_Item());
                form.Show(this);
            }
            if (e.KeyCode == Keys.F7)
            {
                search_filter_cmb.Focus();
                search_filter_cmb.ShowPopup();
            }
            if (e.KeyCode == Keys.F5 || (e.Control && e.KeyCode == Keys.R))
            {
                Refresh_Grid_Data();
            }

        }

        private void search_inp_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }

        private void search_filter_cmb_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }

        private void is_active_item_chkbx_KeyDown(object sender, KeyEventArgs e)
